import 'package:cloud_firestore/cloud_firestore.dart';import 'package:flutter/material.dart';import '../chat/chat_screen.dart';
class ProductDetailScreen extends StatelessWidget{final String productId;const ProductDetailScreen({super.key,required this.productId});@override Widget build(BuildContext c)=>StreamBuilder<DocumentSnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('products').doc(productId).snapshots(),builder:(c,s){if(!s.hasData)return const Scaffold(body:Center(child:CircularProgressIndicator()));final x=s.data!.data();if(x==null)return const Scaffold(body:Center(child:Text('Iklan tidak ditemukan')));return Scaffold(appBar:AppBar(title:const Text('Detail Iklan')),body:ListView(padding:const EdgeInsets.all(20),children:[if(x['imageUrl']?.toString().isNotEmpty==true)ClipRRect(borderRadius:BorderRadius.circular(20),child:Image.network(x['imageUrl'],height:260,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const SizedBox(height:180,child:Center(child:Icon(Icons.image,size:80))))),const SizedBox(height:16),Text(x['title']??'',style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold)),Text('Rp '+(x['price']??0).toString(),style:const TextStyle(fontSize:23,color:Color(0xFF0866FF),fontWeight:FontWeight.bold)),const SizedBox(height:14),Text('📍 '+(x['locationName']??'Lokasi penjual')),const Divider(height:32),const Text('Deskripsi',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text(x['description']??'Belum ada deskripsi.'),const Divider(height:32),ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(x['sellerName']??'Penjual'),subtitle:const Text('Penjual lokal') ),const SizedBox(height:10),FilledButton.icon(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ChatScreen(sellerId:x['sellerId']??'',sellerName:x['sellerName']??'Penjual',productId:productId,productTitle:x['title']??''))),icon:const Icon(Icons.chat_bubble_outline),label:const Text('Chat Penjual'))]));});}